import {
  Fragment,
  createElement,
  isValidElement,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { mergeClasses } from "./classes";
import { surfaceRoundedClasses, type SurfaceRounded } from "./form";
import { Spinner } from "./Spinner";
import type { Shadow, ThemeInput } from "./theme";
import {
  BalsaThemeContext,
  useResolvedThemeProps,
} from "./theme-context";
import type { SemanticColor } from "./types";

export type TableVariant = "surface" | "outline" | "soft" | "glass";
export type TableDensity = "compact" | "default" | "comfortable";
export type TableColor = "neutral" | SemanticColor;
type TableSectionTag = "thead" | "tbody" | "tfoot";

const tableSectionTags: readonly string[] = ["thead", "tbody", "tfoot"];

interface SlotShape {
  rendered: boolean;
  sectioned: boolean;
}

function inspectSlotNodes(
  node: ReactNode,
  shape: SlotShape = { rendered: false, sectioned: false },
): SlotShape {
  if (node === null || node === undefined || typeof node === "boolean") return shape;
  if (Array.isArray(node)) {
    for (const child of node) inspectSlotNodes(child, shape);
    return shape;
  }
  if (typeof node === "string" || typeof node === "number") {
    if (String(node).trim()) shape.rendered = true;
    return shape;
  }
  if (!isValidElement(node)) return shape;
  if (node.type === Fragment) {
    inspectSlotNodes((node.props as { children?: ReactNode }).children, shape);
    return shape;
  }
  shape.rendered = true;
  if (typeof node.type === "string" && tableSectionTags.includes(node.type)) {
    shape.sectioned = true;
  }
  return shape;
}

function TableSection({
  tag,
  children,
}: {
  tag: TableSectionTag;
  children?: ReactNode;
}) {
  const shape = inspectSlotNodes(children);
  if (!shape.rendered || shape.sectioned) return children ?? null;
  return createElement(tag, null, children);
}

export interface TableProps extends HTMLAttributes<HTMLDivElement> {
  caption: string;
  variant?: TableVariant;
  density?: TableDensity;
  headerColor?: TableColor;
  rowColor?: TableColor;
  striped?: boolean;
  hover?: boolean;
  gridlines?: boolean;
  stickyHeader?: boolean;
  loading?: boolean;
  empty?: boolean;
  emptyText?: string;
  columnCount?: number;
  rounded?: SurfaceRounded;
  shadow?: Shadow;
  theme?: ThemeInput;
  header?: ReactNode;
  footer?: ReactNode;
  emptyContent?: ReactNode;
  children?: ReactNode;
}

const variantClasses: Readonly<Record<TableVariant, string[]>> = {
  surface: ["border-balsa-border", "bg-balsa-surface"],
  outline: ["border-balsa-border-strong", "bg-transparent"],
  soft: ["border-transparent", "bg-balsa-muted"],
  glass: ["border-balsa-border/60", "bg-balsa-surface/60", "backdrop-balsa"],
};
const densityClasses: Readonly<Record<TableDensity, string>> = {
  compact: "text-xs",
  default: "text-sm",
  comfortable: "text-base",
};
const stickyHeaderClasses: Readonly<Record<TableVariant, string[]>> = {
  surface: ["[&_thead]:bg-balsa-surface"],
  outline: ["[&_thead]:bg-balsa-background"],
  soft: ["[&_thead]:bg-balsa-muted"],
  glass: ["[&_thead]:bg-balsa-surface/80", "[&_thead]:backdrop-balsa"],
};
const headerColorClasses: Readonly<Record<TableColor, string[]>> = {
  neutral: [],
  primary: ["[&_thead_th]:bg-balsa-primary/15", "[&_thead_th]:text-balsa-primary"],
  secondary: ["[&_thead_th]:bg-balsa-secondary/15", "[&_thead_th]:text-balsa-secondary"],
  accent: ["[&_thead_th]:bg-balsa-accent/15", "[&_thead_th]:text-balsa-accent"],
  info: ["[&_thead_th]:bg-balsa-info/15", "[&_thead_th]:text-balsa-info"],
  success: ["[&_thead_th]:bg-balsa-success/15", "[&_thead_th]:text-balsa-success"],
  warning: ["[&_thead_th]:bg-balsa-warning/15", "[&_thead_th]:text-balsa-warning"],
  destructive: ["[&_thead_th]:bg-balsa-destructive/15", "[&_thead_th]:text-balsa-destructive"],
};
const rowColorClasses: Readonly<Record<TableColor, string[]>> = {
  neutral: [],
  primary: ["[&_tbody_tr]:bg-balsa-primary/10", "[&_tbody_th]:text-balsa-primary", "[&_tbody_td]:text-balsa-primary"],
  secondary: ["[&_tbody_tr]:bg-balsa-secondary/10", "[&_tbody_th]:text-balsa-secondary", "[&_tbody_td]:text-balsa-secondary"],
  accent: ["[&_tbody_tr]:bg-balsa-accent/10", "[&_tbody_th]:text-balsa-accent", "[&_tbody_td]:text-balsa-accent"],
  info: ["[&_tbody_tr]:bg-balsa-info/10", "[&_tbody_th]:text-balsa-info", "[&_tbody_td]:text-balsa-info"],
  success: ["[&_tbody_tr]:bg-balsa-success/10", "[&_tbody_th]:text-balsa-success", "[&_tbody_td]:text-balsa-success"],
  warning: ["[&_tbody_tr]:bg-balsa-warning/10", "[&_tbody_th]:text-balsa-warning", "[&_tbody_td]:text-balsa-warning"],
  destructive: ["[&_tbody_tr]:bg-balsa-destructive/10", "[&_tbody_th]:text-balsa-destructive", "[&_tbody_td]:text-balsa-destructive"],
};
const stripedRowClasses: Readonly<Record<TableColor, string>> = {
  neutral: "[&_tbody_tr:nth-child(even)]:bg-balsa-muted/60",
  primary: "[&_tbody_tr:nth-child(even)]:bg-balsa-primary/15",
  secondary: "[&_tbody_tr:nth-child(even)]:bg-balsa-secondary/15",
  accent: "[&_tbody_tr:nth-child(even)]:bg-balsa-accent/15",
  info: "[&_tbody_tr:nth-child(even)]:bg-balsa-info/15",
  success: "[&_tbody_tr:nth-child(even)]:bg-balsa-success/15",
  warning: "[&_tbody_tr:nth-child(even)]:bg-balsa-warning/15",
  destructive: "[&_tbody_tr:nth-child(even)]:bg-balsa-destructive/15",
};
const hoverRowClasses: Readonly<Record<TableColor, string>> = {
  neutral: "[&_tbody_tr]:transition-colors [&_tbody_tr:hover]:bg-balsa-selected/60",
  primary: "[&_tbody_tr]:transition-colors [&_tbody_tr:hover]:bg-balsa-primary/20",
  secondary: "[&_tbody_tr]:transition-colors [&_tbody_tr:hover]:bg-balsa-secondary/20",
  accent: "[&_tbody_tr]:transition-colors [&_tbody_tr:hover]:bg-balsa-accent/20",
  info: "[&_tbody_tr]:transition-colors [&_tbody_tr:hover]:bg-balsa-info/20",
  success: "[&_tbody_tr]:transition-colors [&_tbody_tr:hover]:bg-balsa-success/20",
  warning: "[&_tbody_tr]:transition-colors [&_tbody_tr:hover]:bg-balsa-warning/20",
  destructive: "[&_tbody_tr]:transition-colors [&_tbody_tr:hover]:bg-balsa-destructive/20",
};
const selectedRowClasses = [
  "[&_tbody_tr[data-selected=true]]:bg-balsa-selected",
  "[&_tbody_tr[data-selected=true]_th]:text-balsa-selected-foreground",
  "[&_tbody_tr[data-selected=true]_td]:text-balsa-selected-foreground",
];

export function Table(rawProps: TableProps) {
  const { props, theme } = useResolvedThemeProps("table", "surfaces", rawProps, {
    variant: "surface",
    density: "default",
    rounded: "auto",
    shadow: "auto",
  } as const);
  const {
    caption,
    variant,
    density,
    headerColor = "neutral",
    rowColor = "neutral",
    striped = false,
    hover = true,
    gridlines = false,
    stickyHeader = false,
    loading = false,
    empty = false,
    emptyText = "No rows to display.",
    columnCount = 1,
    rounded,
    shadow,
    theme: _themeInput,
    header,
    footer,
    emptyContent,
    children,
    className,
    style,
    ...domProps
  } = props;
  void _themeInput;

  const classes = mergeClasses(
    "max-w-full overflow-x-auto text-balsa-foreground",
    variantClasses[variant],
    surfaceRoundedClasses[rounded],
    className,
  );
  const tableClasses = mergeClasses(
    "w-full min-w-max border-collapse text-left",
    densityClasses[density],
    "[&_th]:font-medium [&_th]:text-balsa-muted-foreground [&_tr]:border-b [&_tr]:border-balsa-border [&_tbody_tr:last-child]:border-b-0",
    headerColorClasses[headerColor],
    rowColorClasses[rowColor],
    striped && stripedRowClasses[rowColor],
    hover && hoverRowClasses[rowColor],
    selectedRowClasses,
    gridlines && "[&_th]:border-r [&_th]:border-balsa-border [&_td]:border-r [&_td]:border-balsa-border",
    stickyHeader && [
      "[&_thead]:sticky",
      "[&_thead]:top-0",
      "[&_thead]:z-10",
      stickyHeaderClasses[variant],
    ],
  );

  return (
    <BalsaThemeContext.Provider value={theme}>
      <div
        {...domProps}
        data-balsa="table"
        data-rounded={rounded}
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-variant={variant}
        data-density={density}
        data-header-color={headerColor}
        data-row-color={rowColor}
        data-shadow={shadow}
        className={classes}
        style={
          {
            ...theme.explicitPresentation?.style,
            ...style,
          } as CSSProperties
        }
      >
        <table className={tableClasses}>
          <caption className="sr-only">{caption}</caption>
          <TableSection tag="thead">{header}</TableSection>
          {loading ? (
            <tbody>
              <tr>
                <td colSpan={columnCount} className="text-center">
                  <Spinner label="Loading rows" />
                </td>
              </tr>
            </tbody>
          ) : empty ? (
            <tbody>
              <tr>
                <td colSpan={columnCount} className="text-center text-balsa-muted-foreground">
                  {emptyContent ?? emptyText}
                </td>
              </tr>
            </tbody>
          ) : (
            <TableSection tag="tbody">{children}</TableSection>
          )}
          <TableSection tag="tfoot">{footer}</TableSection>
        </table>
      </div>
    </BalsaThemeContext.Provider>
  );
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

import { CircleAlert, CircleCheckBig } from "lucide-react";
import type { IconComponent } from "./Icon";

export const fieldLabelClasses =
  "mb-balsa-2xs block text-sm font-medium leading-snug text-balsa-foreground";

export const fieldHintClasses = "mt-balsa-2xs block text-sm text-balsa-muted-foreground";

export const textControlClasses =
  "w-full rounded-lg border font-balsa-body text-balsa-input-foreground outline-none transition-[border-color,box-shadow,opacity] placeholder:text-balsa-muted-foreground focus:border-balsa-focus-ring focus:ring-2 focus:ring-balsa-focus-ring/30 disabled:border-balsa-border disabled:bg-balsa-disabled disabled:text-balsa-disabled-foreground";

export const textControlPopupClasses =
  "max-h-64 overflow-auto rounded-lg p-balsa-3xs text-balsa-surface-elevated-foreground shadow-balsa-surface transition-[opacity,transform,visibility] duration-balsa-fast ease-balsa";

export const textControlOptionClasses =
  "flex min-h-8 w-full items-center justify-between rounded-md px-balsa-sm py-balsa-2xs text-left text-sm transition-colors";

/*
 * No bare `border`. Tailwind compiles it to a literal 1px, which outranks the
 * `border-width: var(--balsa-border-width)` the stylesheet sets on these
 * controls -- so a checkbox and a radio kept a 1px edge at every border
 * setting while everything around them moved. The colour utilities stay; only
 * the width comes from the token.
 */
export const choiceInputClasses =
  "shrink-0 cursor-pointer appearance-none outline-none transition-[border-color,background-color,box-shadow,opacity] focus-visible:border-balsa-focus-ring focus-visible:ring-2 focus-visible:ring-balsa-focus-ring/30 disabled:cursor-not-allowed disabled:border-balsa-border disabled:bg-balsa-disabled";

export type FieldStatus = "default" | "validated" | "unvalidated";
export type FieldSize = "sm" | "md";
export type FieldVariant = "outline" | "surface" | "soft" | "glass";
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type TextareaResize = "none" | "vertical" | "both";

export const roundedClasses: Readonly<Record<Rounded, string>> = {
  none: "rounded-none",
  sm: "rounded-sm",
  md: "rounded-md",
  lg: "rounded-lg",
  xl: "rounded-xl",
  "2xl": "rounded-2xl",
  "3xl": "rounded-3xl",
  full: "rounded-full",
};

/**
 * A surface that may be contained by another one.
 *
 * `auto` means "concentric with whatever contains me": the corner follows the
 * containing surface's radius minus the inset between them, so the gap between
 * the two edges stays even instead of thickening at every corner. A surface
 * standing on its own finds nothing published to nest inside and keeps the
 * ordinary surface radius.
 *
 * Kept apart from `Rounded` because that union is shared with text controls,
 * where there is nothing to be concentric with and `auto` would be a value
 * nobody could act on.
 */
export type SurfaceRounded = Rounded | "auto";

export const surfaceRoundedClasses: Readonly<Record<SurfaceRounded, string>> = {
  ...roundedClasses,
  // Deliberately no class. The radius comes from the concentric rule in
  // balsa-theme.css, keyed on data-rounded="auto"; a utility emitted here would
  // outrank it and pin the corner to one value.
  auto: "",
};

const fieldVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-input-border bg-balsa-input",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/70 backdrop-balsa",
};

const fieldPopupVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-border-strong bg-balsa-surface-elevated",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/80 backdrop-balsa",
};

export interface AnchoredPopupPosition {
  left: number;
  top: number;
  width: number;
}

const textControlSizeClasses: Record<FieldSize, string[]> = {
  sm: ["h-8", "px-balsa-md", "text-sm"],
  md: ["h-9", "px-balsa-md", "text-sm"],
};

const textareaResizeClasses: Readonly<Record<TextareaResize, string>> = {
  none: "resize-none",
  vertical: "resize-y",
  both: "resize",
};

export const fieldStatusMessages: Record<
  Extract<FieldStatus, "unvalidated">,
  string
> = {
  unvalidated: "Check this information and try again.",
};

export function getTextControlClasses(
  status: FieldStatus,
  hasAdornment: boolean,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  const resolvedSize = textControlSizeClasses[size] ? size : "md";
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    roundedClasses[rounded],
    ...textControlSizeClasses[resolvedSize],
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-pointer"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getTextControlPopupClasses(
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  return [textControlPopupClasses, roundedClasses[rounded], fieldPopupVariantClasses[variant]];
}

export function getTextareaControlClasses(
  status: FieldStatus,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  resizable: TextareaResize = "vertical",
  hasAdornment = false,
  variant: FieldVariant = "surface",
): string[] {
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    "h-auto min-h-0 py-balsa-xs leading-6",
    roundedClasses[rounded],
    textareaResizeClasses[resizable],
    size === "sm" ? "px-balsa-md text-sm leading-5" : "px-balsa-md text-sm leading-6",
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-text"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getChoiceInputClasses(variant: FieldVariant = "surface"): string[] {
  return [choiceInputClasses, fieldVariantClasses[variant]];
}

export function getChoiceTrackClasses(variant: FieldVariant = "surface"): string {
  return fieldVariantClasses[variant];
}

export function getAnchoredPopupPosition(
  trigger: HTMLElement,
  popup: HTMLElement,
  fallbackHeight = 256,
): AnchoredPopupPosition {
  const triggerRect = trigger.getBoundingClientRect();
  const popupRect = popup.getBoundingClientRect();
  const viewportPadding = 8;
  const gap = 8;
  const width = Math.min(
    triggerRect.width,
    window.innerWidth - viewportPadding * 2,
  );
  const height = popupRect.height || fallbackHeight;
  const maxLeft = Math.max(
    viewportPadding,
    window.innerWidth - width - viewportPadding,
  );

  return {
    width,
    left: Math.min(Math.max(triggerRect.left, viewportPadding), maxLeft),
    top:
      triggerRect.bottom + gap + height <= window.innerHeight - viewportPadding
        ? triggerRect.bottom + gap
        : Math.max(viewportPadding, triggerRect.top - height - gap),
  };
}

export function getFieldStatusIcon(status: FieldStatus): IconComponent | undefined {
  if (status === "validated") return CircleCheckBig;
  if (status === "unvalidated") return CircleAlert;
  return undefined;
}

export function getFieldStateColorClass(status: FieldStatus): string {
  if (status === "unvalidated") return "text-balsa-destructive";
  if (status === "validated") return "text-balsa-success";
  return "text-balsa-muted-foreground";
}
